tool_input.command:
mkdir -p migrations/down
cat > migrations/002_orders_amount_cents.sql <<'EOF'
-- Expand step of renaming orders.total_cents -> amount_cents.
-- The old column stays until a later deploy; the trigger keeps both in sync so old and new app versions both work.
set lock_timeout = '5s';

alter table orders add column amount_cents integer;

create function orders_sync_amount_cents() returns trigger language plpgsql as $$
begin
  if new.amount_cents is null then
    new.amount_cents := new.total_cents;
  elsif new.total_cents is null then
    new.total_cents := new.amount_cents;
  elsif tg_op = 'UPDATE' and new.amount_cents is distinct from old.amount_cents then
    new.total_cents := new.amount_cents;
  else
    new.amount_cents := new.total_cents;
  end if;
  return new;
end $$;

create trigger orders_sync_amount_cents before insert or update on orders
  for each row execute function orders_sync_amount_cents();
EOF
cat > migrations/down/002_orders_amount_cents.sql <<'EOF'
drop trigger orders_sync_amount_cents on orders;
drop function orders_sync_amount_cents();
alter table orders drop column amount_cents;
EOF
cat > src/backfill-amount-cents.ts <<'EOF'
// Batched backfill for orders.amount_cents (run after migration 002, repeat until done). Usage: tsx src/backfill-amount-cents.ts
import { pool } from "./db.ts";

let n: number;
do {
  n = (await pool.query(
    "update orders set amount_cents = total_cents where id in (select id from orders where amount_cents is null limit 5000)",
  )).rowCount ?? 0;
  console.log(`backfilled ${n}`);
} while (n > 0);
await pool.end();
EOF
sed -i '' 's/select id, status, total_cents,/select id, status, amount_cents,/' src/app.ts
sed -i '' 's/(user_id, status, total_cents, payment_id)/(user_id, status, amount_cents, payment_id)/' db/seed.sql
pnpm db:reset 2>&1 | tail -5; pnpm typecheck 2>&1 | tail -5; pnpm test 2>&1 | tail -8
psql "$(grep -o 'postgres://[^"]*' src/db.ts | head -1)" -c "select id,total_cents,amount_cents from orders" 2>&1 | tail -6
